 "content": "def transform(grid):
    """Fill grid cells (tiles) along aligned pairs of same-colored markers.

    Full 8 rows/columns are dividers. A marker in a tile sends its color
    along the tile row/column to aligned markers; intersecting 2 and 3
    signals are shown as color 6.
    """
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r, row in enumerate(grid) if all(v == 8 for v in row)]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    row_ranges = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))
    col_ranges = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    markers = {}
    for tr, (r0, r1) in enumerate(row_ranges):
        for tc, (c0, c1) in enumerate(col_ranges):
            colors = {grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, 8)}
            for color in colors:
                markers.setdefault(color, []).append((tr, tc))

    signals = {}
    for color, points in markers.items():
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                if r1 == r2:
                    for tc in range(min(c1, c2), max(c1, c2) + 1):
                        signals.setdefault((r1, tc), set()).add(color)
                if c1 == c2:
                    for tr in range(min(r1, r2), max(r1, r2) + 1):
                        signals.setdefault((tr, c1), set()).add(color)

    out = [row[:] for row in grid]
    for (tr, tc), colors in signals.items():
        r0, r1 = row_ranges[tr]
        c0, c1 = col_ranges[tc]
        value = 6 if 2 in colors and 3 in colors else min(colors)
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = value
    return out
